import React from 'react';import {createRoot}from'react-dom/client';import {PackageBatchPreview}from'../../app/package-batch-preview';
const products=[{sku:'fillerday',name:'Day Cream'},{sku:'fillernight',name:'Night Cream'}];
(window as any).posts=[];
window.fetch=async(url,init)=>{const path=String(url);let data:any;if(path.includes('inventory-skus')){const p=new URL(path,location.origin).searchParams,q=(p.get('q')??'').toLowerCase();data={products:products.filter(v=>p.has('sku')?v.sku===p.get('sku')||v.name===p.get('name'):(v.name+' '+v.sku).toLowerCase().includes(q)),canEdit:false};}else if(path.includes('package-batch-review')){const body=JSON.parse(String(init?.body));data={rows:body.rows.map((r:any)=>({...r,catalogRequired:true,items:r.items.map((i:any)=>({...i,name:products.find(p=>p.sku===i.sku)?.name??i.name})),...(r.exportId?{exportSnapshot:{id:r.exportId,normal:100,campaign:90,scenarios:[{serviceScenario:'Non-Campaign Day',facebookPrice:100,suggestedShopeePrice:100,pricingGoal:'sameCustomerPrice'},{serviceScenario:'Campaign Day',facebookPrice:100,suggestedShopeePrice:90,pricingGoal:'sameCustomerPrice'}]}}:{})})),products};}else{const b=JSON.parse(String(init?.body));(window as any).posts.push(b);data={ok:true,packageId:b.clientRequestId};}return new Response(JSON.stringify(data));};
createRoot(document.getElementById('root')!).render(<PackageBatchPreview storeId="shopee-berlanco-beauty-official" storeName="Berlanco" onExit={message=>{(window as any).exitMessage=message;}}/>);
